import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Central & Tenant Databases","description":"Central and tenant databases in the kits: migrations, seeders, tenant database naming, what drops a tenant database and the key tables in each.","frontmatter":{"title":"Central & Tenant Databases","description":"Central and tenant databases in the kits: migrations, seeders, tenant database naming, what drops a tenant database and the key tables in each.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/core/database.html"}],["meta",{"property":"og:title","content":"Central & Tenant Databases"}],["meta",{"property":"og:description","content":"Central and tenant databases in the kits: migrations, seeders, tenant database naming, what drops a tenant database and the key tables in each."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/core/database.html"}],["meta",{"name":"twitter:title","content":"Central & Tenant Databases"}],["meta",{"name":"twitter:description","content":"Central and tenant databases in the kits: migrations, seeders, tenant database naming, what drops a tenant database and the key tables in each."}]]},"headers":[],"relativePath":"docs/core/database.md","filePath":"docs/core/database.md","lastUpdated":1790486087000}'),n={name:"docs/core/database.md"};function s(c,e,r,i,l,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h1><p>The kits use two kinds of databases on the same server. Each tenant&#39;s data is physically separate, so one tenant can never query another tenant&#39;s rows.</p><table tabindex="0"><thead><tr><th></th><th>Central database</th><th>Tenant database</th></tr></thead><tbody><tr><td>Name</td><td><code>DB_DATABASE</code></td><td><code>tenant&lt;id&gt;</code>, one per tenant</td></tr><tr><td>Holds</td><td>Tenants, domains, central users, global settings, the queue</td><td>That tenant&#39;s users, roles, menus and sessions</td></tr><tr><td>Migrations</td><td><code>database/migrations</code></td><td><code>database/migrations/tenant</code></td></tr><tr><td>Seeder</td><td><code>DatabaseSeeder</code></td><td><code>tenant\\TenantDatabaseSeeder</code></td></tr></tbody></table><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p>Each context has its own migration folder and command.</p><table tabindex="0"><thead><tr><th>Folder</th><th>Runs on</th><th>Command</th></tr></thead><tbody><tr><td><code>database/migrations</code></td><td>Central database</td><td><code>php artisan migrate</code></td></tr><tr><td><code>database/migrations/tenant</code></td><td>Every tenant database</td><td><code>php artisan tenants:migrate</code> (also runs automatically when a tenant is created)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Put migrations in the right folder</p><p>A migration in <code>database/migrations</code> never reaches tenant databases, and vice versa. Tables that both contexts need (users, menus, permissions, cache, jobs) exist in both folders.</p></div><p>A tenant table, for example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make:migration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create_projects_table</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path=database/migrations/tenant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tenants:migrate</span></span></code></pre></div><p>Other tenant commands (all accept <code>--tenants=&lt;id&gt;</code> to target specific tenants):</p><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>tenants:rollback</code></td><td>Roll back tenant migrations</td></tr><tr><td><code>tenants:migrate-fresh</code></td><td>Drop and re-run tenant migrations</td></tr><tr><td><code>tenants:seed</code></td><td>Run the tenant seeder</td></tr><tr><td><code>tenants:list</code></td><td>List tenants</td></tr><tr><td><code>tenants:run</code></td><td>Run any artisan command per tenant</td></tr></tbody></table><p>The tenant migration path is set by <code>migration_parameters</code> in <code>config/tenancy.php</code>.</p><h2 id="seeders" tabindex="-1">Seeders <a class="header-anchor" href="#seeders" aria-label="Permalink to &quot;Seeders&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Seeder</th><th>Context</th><th>Calls</th></tr></thead><tbody><tr><td><code>Database\\Seeders\\DatabaseSeeder</code></td><td>Central (<code>php artisan db:seed</code>)</td><td><code>RoleSeeder</code>, <code>PermissionSeeder</code>, <code>MenuSeeder</code>, <code>DefaultUserSeeder</code></td></tr><tr><td><code>Database\\Seeders\\tenant\\TenantDatabaseSeeder</code></td><td>Tenant (<code>tenants:seed</code>, tenant creation)</td><td><code>tenant\\RoleSeeder</code>, <code>PermissionSeeder</code>, <code>tenant\\MenuSeeder</code>, <code>DefaultUserSeeder</code></td></tr></tbody></table><p><code>RoleSeeder</code> and <code>PermissionSeeder</code> work in both contexts: they check <code>tenancy()-&gt;initialized</code> to pick the guard (<code>web</code> or <code>tenant</code>) and the permission folder. See <a href="/docs/getting-started/local-development.html#seeded-data">Local development → Seeded data</a>.</p><h2 id="tenant-database-naming" tabindex="-1">Tenant database naming <a class="header-anchor" href="#tenant-database-naming" aria-label="Permalink to &quot;Tenant database naming&quot;">​</a></h2><p>stancl names each tenant database <strong>prefix + tenant id + suffix</strong>. Tenant IDs are auto-increment integers (<code>App\\Models\\Tenant</code>), so the databases are <code>tenant1</code>, <code>tenant2</code>, ...</p><table tabindex="0"><thead><tr><th>Key in <code>config/tenancy.php</code></th><th>Vue, Svelte</th><th>React</th></tr></thead><tbody><tr><td><code>database.prefix</code></td><td><code>&#39;tenant&#39;</code></td><td><code>env(&#39;TENANCY_DB_PREFIX&#39;, &#39;tenant&#39;)</code></td></tr><tr><td><code>database.suffix</code></td><td><code>&#39;&#39;</code></td><td><code>&#39;&#39;</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Sharing a MySQL server</p><p>Two apps using the same prefix on one server both try to create <code>tenant1</code>. Use a unique prefix per app (for example <code>acme_tenant</code>) <strong>before</strong> the first tenant is created. In the React kit set <code>TENANCY_DB_PREFIX</code>; in Vue and Svelte edit <code>config/tenancy.php</code>.</p></div><table tabindex="0"><thead><tr><th>Action</th><th>Tenant database</th></tr></thead><tbody><tr><td>Delete a tenant in the UI</td><td>Dropped (<code>TenantDeleted</code> → <code>DeleteDatabase</code>)</td></tr><tr><td><code>migrate:fresh</code> on the central database</td><td><strong>Not</strong> dropped</td></tr></tbody></table><h2 id="key-tables" tabindex="-1">Key tables <a class="header-anchor" href="#key-tables" aria-label="Permalink to &quot;Key tables&quot;">​</a></h2><h3 id="central" tabindex="-1">Central <a class="header-anchor" href="#central" aria-label="Permalink to &quot;Central&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Model</th><th>Notes</th></tr></thead><tbody><tr><td><code>users</code></td><td><code>App\\Models\\User</code></td><td>Includes <code>locale</code>, <code>invited_at</code>, 2FA columns</td></tr><tr><td><code>tenants</code></td><td><code>App\\Models\\Tenant</code></td><td><code>first_name</code>, <code>last_name</code>, <code>email</code>, <code>phone</code>, <code>company</code>, <code>team_size</code> + <code>data</code> JSON (industry, status, work week, ...)</td></tr><tr><td><code>domains</code></td><td><code>App\\Models\\Domain</code></td><td><code>domain</code> (unique), <code>tenant_id</code>, <code>is_primary</code>, <code>locale</code>, <code>app_name</code>, <code>auth_features</code> JSON</td></tr><tr><td><code>menus</code></td><td><code>App\\Models\\Menu</code></td><td>Central navigation</td></tr><tr><td><code>layout_settings</code></td><td><code>App\\Models\\LayoutSetting</code></td><td><code>user_id = null</code> row is the global default</td></tr><tr><td><code>settings</code></td><td><code>App\\Models\\Setting</code></td><td>Key/JSON value store (e.g. <code>tenant_maintenance</code>)</td></tr><tr><td><code>roles</code>, <code>permissions</code>, <code>model_has_*</code>, <code>role_has_permissions</code></td><td>spatie</td><td>Guard <code>web</code></td></tr><tr><td><code>passkeys</code></td><td>Fortify</td><td></td></tr><tr><td><code>sessions</code>, <code>cache</code>, <code>cache_locks</code>, <code>password_reset_tokens</code></td><td>Laravel</td><td></td></tr><tr><td><code>jobs</code>, <code>job_batches</code>, <code>failed_jobs</code></td><td>Laravel</td><td>Used by all tenants (see <a href="/docs/getting-started/configuration.html#config-queue-php">Configuration</a>)</td></tr></tbody></table><h3 id="tenant" tabindex="-1">Tenant <a class="header-anchor" href="#tenant" aria-label="Permalink to &quot;Tenant&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>users</code>, <code>password_reset_tokens</code>, <code>sessions</code></td><td>Tenant accounts</td></tr><tr><td><code>passkeys</code></td><td></td></tr><tr><td><code>menus</code>, <code>layout_settings</code></td><td>Tenant navigation and layouts</td></tr><tr><td><code>roles</code>, <code>permissions</code>, pivots</td><td>Guard <code>tenant</code></td></tr><tr><td><code>cache</code>, <code>cache_locks</code></td><td></td></tr><tr><td><code>jobs</code>, <code>job_batches</code>, <code>failed_jobs</code></td><td>Created, but the queue writes to the central connection</td></tr></tbody></table><h2 id="testing-database" tabindex="-1">Testing database <a class="header-anchor" href="#testing-database" aria-label="Permalink to &quot;Testing database&quot;">​</a></h2><p>Tests never touch MySQL: <code>phpunit.xml</code> uses SQLite in memory (<code>DB_CONNECTION=sqlite</code>, <code>DB_DATABASE=:memory:</code>), and Pest applies <code>RefreshDatabase</code> to <code>tests/Feature</code>. See <a href="/docs/core/testing.html">Testing</a>.</p>`,27)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
